#!/usr/bin/env node
/**
 * G18 — prove original private backup bytes equal EVERY restored object.
 * Run ONLY on a protected terminal with the CLONE secret and the private
 * directory generated by scripts/backup/export_private_storage.py.
 * Never accept production credentials or print paths, keys or file data.
 */
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import {createReadStream,existsSync,lstatSync,readFileSync,realpathSync,statSync} from 'node:fs';
import {join,isAbsolute,resolve,sep} from 'node:path';
import {pathToFileURL} from 'node:url';

const CLONE='https://zjgstfgiirgjssnihaam.supabase.co';
const MAX_FILES=10000;
const MAX_OBJECT_BYTES=30*1024*1024;
const UUID_SHA=/^[a-f0-9]{64}$/i;
const DENY='Restauración de archivos privados NO verificada; lanzamiento bloqueado';
const fail=()=>new Error(DENY);

function safeParts(value) {
 if(typeof value!=='string' || !value || value.length>1024 ||
   value.includes('\\') || value.includes('\0')) throw fail();
 const parts=value.split('/');
 if(parts.length>20 || parts.some(p=>!p || p==='.' || p==='..' ||
    /[\x00-\x1f]/.test(p) || p.length>200)) throw fail();
 return parts;
}
function safeBucket(bucket) {
 if(typeof bucket!=='string' || !/^[a-z0-9][a-z0-9_-]{1,100}$/.test(bucket))
   throw fail();
 return bucket;
}
const identity=(bucket,path)=>bucket+'\0'+path;

/** Exact paths/sizes/hashes from original offline export, no data exposure. */
export function validateStorageManifest(rows) {
 if(!Array.isArray(rows)||rows.length>MAX_FILES)throw fail();
 const seen=new Set();
 return rows.map(entry=>{
   const bucket=safeBucket(entry?.bucket);
   safeParts(entry?.path);
   if(!Number.isSafeInteger(entry?.bytes) || entry.bytes<1 ||
      entry.bytes>MAX_OBJECT_BYTES || !UUID_SHA.test(entry?.sha256??''))
     throw fail();
   const id=identity(bucket,entry.path);
   if(seen.has(id))throw fail();
   seen.add(id);
   return {bucket,path:entry.path,bytes:entry.bytes,sha256:entry.sha256.toLowerCase()};
 });
}

/** Reject manifests that omit or invent even one restored Storage object. */
export function assertExactStorageCoverage(manifest,objects) {
 if(!Array.isArray(manifest)||!(objects instanceof Set)||manifest.length!==objects.size)
   throw fail();
 for(const entry of manifest){
   if(!objects.has(identity(entry.bucket,entry.path)))throw fail();
 }
 return true;
}

async function sha256Local(file,expectedBytes) {
 const hash=createHash('sha256');let count=0;
 for await(const chunk of createReadStream(file)){
   count+=chunk.length;
   if(count>MAX_OBJECT_BYTES)throw fail();
   hash.update(chunk);
 }
 if(count!==expectedBytes)throw fail();
 return hash.digest('hex');
}

async function sha256Remote(response,expectedBytes) {
 if(!response.ok || !response.body || response.url &&
   new URL(response.url).origin!==CLONE)throw fail();
 const hash=createHash('sha256');let count=0;
 const reader=response.body.getReader();
 try{
   while(true){
     const {done,value}=await reader.read();
     if(done)break;
     count+=value.byteLength;
     if(count>MAX_OBJECT_BYTES || count>expectedBytes)throw fail();
     hash.update(value);
   }
 }finally{reader.releaseLock();}
 if(count!==expectedBytes)throw fail();
 return hash.digest('hex');
}
function privateFile(root,bucket,path){
 const parts=['storage',bucket,...safeParts(path)];
 let file=root;
 for(const part of parts){
   file=join(file,part);
   // Never follow symlinks to secrets or files from outside the private backup.
   if(!existsSync(file) || lstatSync(file).isSymbolicLink())throw fail();
 }
 if(!file.startsWith(root+sep) || !statSync(file).isFile())throw fail();
 return file;
}
async function storageFetch(fetchImpl,url,secret,options={}){
 const response=await fetchImpl(url,{
   ...options,redirect:'error',signal:AbortSignal.timeout(30000),
   headers:{
     apikey:secret,Authorization:'Bearer '+secret,
     ...(options.body?{'content-type':'application/json'}:{}),
   },
 });
 if(!response.ok)throw fail();
 return response;
}
async function listRestoredObjects(fetchImpl,secret) {
 const buckets=await(await storageFetch(fetchImpl,CLONE+'/storage/v1/bucket',secret)).json();
 if(!Array.isArray(buckets))throw fail();
 const objects=new Set(),bucketIds=new Set();
 for(const bucket of buckets){
   const id=safeBucket(bucket?.id);
   if(bucketIds.has(id))throw fail();
   bucketIds.add(id);
   const prefixes=[''];
   let folders=0;
   while(prefixes.length){
     const prefix=prefixes.pop();
     for(let offset=0;;offset+=100){
       if(offset>MAX_FILES*2)throw fail();
       const payload=JSON.stringify({prefix,limit:100,offset});
       const r=await storageFetch(fetchImpl,
         CLONE+'/storage/v1/object/list/'+encodeURIComponent(id),
         secret,{method:'POST',body:payload});
       const entries=await r.json();
       if(!Array.isArray(entries) || entries.length>100)throw fail();
       for(const entry of entries){
         const part=safeParts(entry?.name);
         if(part.length!==1)throw fail();
         const path=prefix?prefix+'/'+entry.name:entry.name;
         safeParts(path);
         if(entry.id===null || entry.id===undefined){
           if(++folders>MAX_FILES)throw fail();
           prefixes.push(path);
         }else{
           const key=identity(id,path);
           if(objects.has(key) || objects.size>=MAX_FILES)throw fail();
           objects.add(key);
         }
       }
       if(entries.length<100)break;
     }
   }
 }
 return {objects,bucketCount:bucketIds.size};
}
export async function verifyRestoredStorageBytes({root,manifest,origin,secret,fetchImpl=fetch}) {
 if(origin!==CLONE || typeof secret!=='string' || secret.length<10 ||
   !isAbsolute(root))throw fail();
 const actualRoot=realpathSync(root);
 if(actualRoot!==resolve(root) || !statSync(actualRoot).isDirectory() ||
   (statSync(actualRoot).mode & 0o077)!==0)throw fail();
 const entries=validateStorageManifest(manifest);
 const {objects,bucketCount}=await listRestoredObjects(fetchImpl,secret);
 assertExactStorageCoverage(entries,objects);
 let total=0;
 for(const item of entries){
   const path=privateFile(actualRoot,item.bucket,item.path);
   const local=await sha256Local(path,item.bytes);
   if(local!==item.sha256)throw fail();
   const encoded=safeParts(item.path).map(encodeURIComponent).join('/');
   const url=CLONE+'/storage/v1/object/authenticated/'+
      encodeURIComponent(item.bucket)+'/'+encoded;
   const remote=await sha256Remote(await storageFetch(fetchImpl,url,secret),item.bytes);
   if(remote!==item.sha256)throw fail();
   total+=item.bytes;
 }
 return {objects:entries.length,buckets:bucketCount,verifiedBytes:total};
}
async function main(){
 try{
  assert.equal(process.env.JCO_STORAGE_VERIFY_CLONE,'1','Opt-in required');
  const root=process.argv[2];
  if(!root || !isAbsolute(root))throw fail();
  const manifest=JSON.parse(readFileSync(join(root,'storage-manifest.json'),'utf8'));
  const result=await verifyRestoredStorageBytes({
   root,manifest,origin:process.env.JCO_STORAGE_CLONE_URL,
   secret:process.env.JCO_STORAGE_SECRET_KEY,
  });
  console.log('G18 VERIFIED: '+result.objects+' exact restored private objects, '+
    result.verifiedBytes+' verified bytes, '+result.buckets+' buckets. No PII printed.');
 }catch{
  console.error(DENY);process.exitCode=1;
 }
}
if(process.argv[1] && import.meta.url===pathToFileURL(resolve(process.argv[1])).href)
 await main();
